import{_ as a,o as e,c as r,ag as d}from"./chunks/framework.DMXcdKmJ.js";const _=JSON.parse('{"title":"创建和管理工程","description":"新建工程、理解可见范围、查找与整理工程，并谨慎处理导入导出和删除。","frontmatter":{"title":"创建和管理工程","description":"新建工程、理解可见范围、查找与整理工程，并谨慎处理导入导出和删除。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/projects.md","filePath":"zh/使用指南/创建和管理工程.md"}'),o={name:"zh/guide/projects.md"};function i(h,t,l,n,s,p){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="创建和管理工程" tabindex="-1">创建和管理工程 <a class="header-anchor" href="#创建和管理工程" aria-label="Permalink to &quot;创建和管理工程&quot;">​</a></h1><p>工程用于组织应用源码、数据配置和运行资料。使用组织账号进入 <strong>“工程管理”</strong>；管理员、工程人员和运维人员按权限开展工作。</p><p>第一次从零开始，可以先跟随<a href="/induframe-docs/zh/start/first-project.html">创建第一个工程</a>。</p><h2 id="_1-找到工程" tabindex="-1">1. 找到工程 <a class="header-anchor" href="#_1-找到工程" aria-label="Permalink to &quot;1. 找到工程&quot;">​</a></h2><p>页面支持 **“卡片”<strong>和</strong>“列表”**两种视图。搜索可使用工程名称、编码或描述；还可结合标签、分组等条件筛选。</p><p>找不到工程时，先核对组织、搜索条件、页码和可见范围。看到“读取失败”时，先重新读取；不要把尚未加载出的列表当成工程被删除。</p><h2 id="_2-新建工程" tabindex="-1">2. 新建工程 <a class="header-anchor" href="#_2-新建工程" aria-label="Permalink to &quot;2. 新建工程&quot;">​</a></h2><ol><li>点击 <strong>“新建工程”</strong>。</li><li>在“创建工程”对话框填写工程名称，描述可按需要填写。</li><li>点击 <strong>“创建”</strong>，等待结果。</li><li>在列表核对新工程，刷新后再确认一次。</li></ol><p>使用便于辨认且未被占用的名称。工程路径由系统生成，不需要手工编写；修改已有工程名称不会自动更换原访问路径。</p><p>达到工程额度或开发名额限制时，按页面提示联系组织管理员。创建请求结果不明确时，先搜索核对，不要马上连续创建同名工程。</p><p>创建工程记录后，还需要在 **“应用开发”**里完成第一次模板初始化，才能开始维护源码，见<a href="/induframe-docs/zh/guide/workspace.html">使用应用开发工作区</a>。</p><h2 id="_3-理解-私有-和-公开" tabindex="-1">3. 理解“私有”和“公开” <a class="header-anchor" href="#_3-理解-私有-和-公开" aria-label="Permalink to &quot;3. 理解“私有”和“公开”&quot;">​</a></h2><p>新建工程默认是“私有”。</p><table tabindex="0"><thead><tr><th>可见范围</th><th>对本组织意味着什么</th></tr></thead><tbody><tr><td>私有</td><td>创建者和组织管理员可见，其他成员的列表里不显示</td></tr><tr><td>公开</td><td>同组织具有工程功能权限的成员可见，可按权限进入开发；修改基本信息、导出、删除和切换可见范围仍受归属限制</td></tr></tbody></table><p><strong>这里的“公开”不是发布到互联网，也不是免登录访问。</strong> 不同组织的权限仍分别管理。</p><p>需要调整时，从工程提供的操作中选择 <strong>“切换共享状态”</strong>，按提示确认，再核对“可见范围”。</p><h2 id="_4-编辑、分组和标签" tabindex="-1">4. 编辑、分组和标签 <a class="header-anchor" href="#_4-编辑、分组和标签" aria-label="Permalink to &quot;4. 编辑、分组和标签&quot;">​</a></h2><p>通过 **“编辑工程”**调整名称和描述，点击“保存”后重新核对。不想保存时按提示取消或放弃修改。</p><p>标签和分组用于查找与整理工程，不会创建工程副本。组织共享的标签、分组字典由管理员维护；工程创建者或管理员按权限调整工程所属的标签与分组。</p><p>不要把“从分组移除工程”和“删除工程”混为一谈。若提示操作已保存、但列表刷新失败，先重新读取，不必重复提交同一修改。</p><h2 id="_5-选择要进入的功能" tabindex="-1">5. 选择要进入的功能 <a class="header-anchor" href="#_5-选择要进入的功能" aria-label="Permalink to &quot;5. 选择要进入的功能&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>用来做什么</th></tr></thead><tbody><tr><td>应用开发</td><td>选择初始模板、维护源码、使用 AI 和编辑器、查看开发预览</td></tr><tr><td>数据中心</td><td>维护该工程的数据和业务配置</td></tr><tr><td>工程设置</td><td>查看或维护该工程的设置</td></tr><tr><td>发布、部署相关操作</td><td>准备工程版本及运行部署，与浏览器里的开发预览分开处理</td></tr></tbody></table><p>运行状态、部署状态和开发环境状态也不是同一回事，见<a href="/induframe-docs/zh/concepts/development-and-runtime.html">开发、发布与运行</a>。</p><h2 id="_6-导入与导出" tabindex="-1">6. 导入与导出 <a class="header-anchor" href="#_6-导入与导出" aria-label="Permalink to &quot;6. 导入与导出&quot;">​</a></h2><p>导出时，选择有权限的工程并使用 <strong>“导出工程”</strong>；批量操作先选择目标工程。浏览器要求选择保存位置时，完成保存并确认实际取得文件；取消保存不算导出完成。</p><p>导入时点击 <strong>“导入工程”</strong>，选择平台支持的工程归档，等待结果，再核对新工程。不把普通源码压缩包当成平台工程归档。</p><p><strong>工程导出不等于整个运行环境或全部业务数据的备份。</strong> 导入后需要检查连接和采集配置、重新填写被移除的凭据，并在工程身份管理中重置用户密码；内置业务库按配置重建为空库。使用前先核对实际业务。</p><h2 id="_7-删除要先确认" tabindex="-1">7. 删除要先确认 <a class="header-anchor" href="#_7-删除要先确认" aria-label="Permalink to &quot;7. 删除要先确认&quot;">​</a></h2><p>删除无法恢复。先确认工程、依赖、部署和需要保留的数据，再通过“删除”或“批量删除”操作。</p><ul><li>核对确认框里的目标，批量操作时尤其注意选中范围。</li><li>系统提示仍有依赖或部署时，先按提示处理。</li><li>“已受理”表示请求已进入处理，不要靠反复点击加速清理。</li><li>结果不明确或出现错误时，保留提示并联系运维人员。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>开始开发见<a href="/induframe-docs/zh/guide/workspace.html">使用应用开发工作区</a>，检查页面见<a href="/induframe-docs/zh/guide/preview.html">预览工程页面</a>，上传资料见<a href="/induframe-docs/zh/guide/project-files.html">查看和上传工程文件</a>。</p>',32)])])}const u=a(o,[["render",i]]);export{_ as __pageData,u as default};
